func:
// Store RPC info
if (msg.rpcResponseTopic) {
    flow.set("lds_rpc_response_topic", msg.rpcResponseTopic);
}

// Send to all 5 parallel reads
return [msg, msg, msg, msg, msg];

// Daily and Total load energy
// 526: Day load energy (0.1kWh)
// 527-528: Total load energy (0.1kWh, 32-bit)

msg.baseAddr = 526;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 526,
    quantity: 3
};
return msg;

// UPS load power (low) + Load voltage
// 640-643: UPS phase A,B,C,total power (low word)
// 644-646: Load phase A,B,C voltage (0.1V)

msg.baseAddr = 640;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 640,
    quantity: 7
};
return msg;

// Load power (low) + frequency
// 650-653: Load phase A,B,C,total power (low word)
// 654: (skip)
// 655: Load frequency (0.01Hz)

msg.baseAddr = 650;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 650,
    quantity: 6
};
return msg;

// Load power (high word)
// 656-659: Load phase A,B,C,total power (high word)

msg.baseAddr = 656;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 656,
    quantity: 4
};
return msg;

// UPS load power (high word)
// 696-699: UPS phase A,B,C,total power (high word)

msg.baseAddr = 696;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 696,
    quantity: 4
};
return msg;

// Build LoadDeviceState from 5 parallel Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("LoadDeviceState: missing base address");
    return null;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// Helper: combine two 16-bit words to 32-bit signed
function s32(low, high) {
    const val = u32(low, high);
    return (val & 0x80000000) ? val - 0x100000000 : val;
}

// ---- Store partials ----

// Energy 526-528
if (baseAddr === 526) {
    const dailyRaw = data[0] || 0;      // 526
    const totalLow = data[1] || 0;      // 527
    const totalHigh = data[2] || 0;     // 528

    flow.set("lds_part_energy", {
        todayEnergyKWh: Math.round(dailyRaw * 0.1 * 10) / 10,
        totalEnergyKWh: Math.round(u32(totalLow, totalHigh) * 0.1 * 10) / 10
    });
}

// UPS/Voltage 640-646
else if (baseAddr === 640) {
    const upsALow = data[0] || 0;       // 640
    const upsBLow = data[1] || 0;       // 641
    const upsCLow = data[2] || 0;       // 642
    const upsTotalLow = data[3] || 0;   // 643
    const voltageA = data[4] || 0;      // 644 (0.1V)
    const voltageB = data[5] || 0;      // 645 (0.1V)
    const voltageC = data[6] || 0;      // 646 (0.1V)

    flow.set("lds_part_ups_voltage", {
        upsALow: upsALow,
        upsBLow: upsBLow,
        upsCLow: upsCLow,
        upsTotalLow: upsTotalLow,
        phaseAVoltageV: Math.round(voltageA * 0.1 * 10) / 10,
        phaseBVoltageV: Math.round(voltageB * 0.1 * 10) / 10,
        phaseCVoltageV: Math.round(voltageC * 0.1 * 10) / 10
    });
}

// Load/Freq 650-655
else if (baseAddr === 650) {
    const loadALow = data[0] || 0;      // 650
    const loadBLow = data[1] || 0;      // 651
    const loadCLow = data[2] || 0;      // 652
    const loadTotalLow = data[3] || 0;  // 653
    // data[4] = 654 (skip)
    const freq = data[5] || 0;          // 655 (0.01Hz)

    flow.set("lds_part_load_freq", {
        loadALow: loadALow,
        loadBLow: loadBLow,
        loadCLow: loadCLow,
        loadTotalLow: loadTotalLow,
        frequencyHz: Math.round(freq * 0.01 * 100) / 100
    });
}

// Load High 656-659
else if (baseAddr === 656) {
    const loadAHigh = data[0] || 0;     // 656
    const loadBHigh = data[1] || 0;     // 657
    const loadCHigh = data[2] || 0;     // 658
    const loadTotalHigh = data[3] || 0; // 659

    flow.set("lds_part_load_high", {
        loadAHigh: loadAHigh,
        loadBHigh: loadBHigh,
        loadCHigh: loadCHigh,
        loadTotalHigh: loadTotalHigh
    });
}

// UPS High 696-699
else if (baseAddr === 696) {
    const upsAHigh = data[0] || 0;      // 696
    const upsBHigh = data[1] || 0;      // 697
    const upsCHigh = data[2] || 0;      // 698
    const upsTotalHigh = data[3] || 0;  // 699

    flow.set("lds_part_ups_high", {
        upsAHigh: upsAHigh,
        upsBHigh: upsBHigh,
        upsCHigh: upsCHigh,
        upsTotalHigh: upsTotalHigh
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const energyPart = flow.get("lds_part_energy");
const upsVoltagePart = flow.get("lds_part_ups_voltage");
const loadFreqPart = flow.get("lds_part_load_freq");
const loadHighPart = flow.get("lds_part_load_high");
const upsHighPart = flow.get("lds_part_ups_high");

if (!energyPart || !upsVoltagePart || !loadFreqPart || !loadHighPart || !upsHighPart) {
    return null;  // Wait for all 5 parts
}

// Combine 32-bit power values
const loadAPower = s32(loadFreqPart.loadALow, loadHighPart.loadAHigh);
const loadBPower = s32(loadFreqPart.loadBLow, loadHighPart.loadBHigh);
const loadCPower = s32(loadFreqPart.loadCLow, loadHighPart.loadCHigh);
const loadTotalPower = s32(loadFreqPart.loadTotalLow, loadHighPart.loadTotalHigh);

const upsAPower = s32(upsVoltagePart.upsALow, upsHighPart.upsAHigh);
const upsBPower = s32(upsVoltagePart.upsBLow, upsHighPart.upsBHigh);
const upsCPower = s32(upsVoltagePart.upsCLow, upsHighPart.upsCHigh);
const upsTotalPower = s32(upsVoltagePart.upsTotalLow, upsHighPart.upsTotalHigh);

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "LoadDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    scope: "backup_load",

    loadPower: {
        totalActivePowerW: loadTotalPower,
        phaseAPowerW: loadAPower,
        phaseBPowerW: loadBPower,
        phaseCPowerW: loadCPower
    },

    loadVoltage: {
        phaseAVoltageV: upsVoltagePart.phaseAVoltageV,
        phaseBVoltageV: upsVoltagePart.phaseBVoltageV,
        phaseCVoltageV: upsVoltagePart.phaseCVoltageV
    },

    frequencyHz: loadFreqPart.frequencyHz,

    upsLoadPower: {
        totalPowerW: upsTotalPower,
        phaseAPowerW: upsAPower,
        phaseBPowerW: upsBPower,
        phaseCPowerW: upsCPower
    },

    todayEnergyKWh: energyPart.todayEnergyKWh,
    totalEnergyKWh: energyPart.totalEnergyKWh
};

// Clear partials
flow.set("lds_part_energy", null);
flow.set("lds_part_ups_voltage", null);
flow.set("lds_part_load_freq", null);
flow.set("lds_part_load_high", null);
flow.set("lds_part_ups_high", null);

// Get RPC info
const rpcResponseTopic = flow.get("lds_rpc_response_topic");
flow.set("lds_rpc_response_topic", null);

flow.set("loadDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

// Only handle messages that came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;
